import 'package:flutter/material.dart';
void main()=>runApp(const FarahChat());
class FarahChat extends StatelessWidget{const FarahChat({super.key});@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'فرح شات',theme:ThemeData(brightness:Brightness.dark,scaffoldBackgroundColor:const Color(0xFF080817),colorScheme:ColorScheme.fromSeed(seedColor:const Color(0xFF9C4DFF),brightness:Brightness.dark),useMaterial3:true),home:const HomePage());}
class HomePage extends StatefulWidget{const HomePage({super.key});@override State<HomePage> createState()=>_HomePageState();}
class _HomePageState extends State<HomePage>{int index=0;final rooms=const ['Royal Lounge','Galaxy Night','Diamond Club'];@override Widget build(BuildContext c){final pages=[ListView(padding:const EdgeInsets.all(16),children:[const Text('فرح شات',style:TextStyle(fontSize:30,fontWeight:FontWeight.w800)),const SizedBox(height:6),const Text('غرف صوتية بتجربة ثلاثية الأبعاد'),const SizedBox(height:18),...rooms.map((r)=>Padding(padding:const EdgeInsets.only(bottom:12),child:Card(child:ListTile(contentPadding:const EdgeInsets.all(14),leading:Container(width:56,height:56,decoration:const BoxDecoration(shape:BoxShape.circle,gradient:LinearGradient(colors:[Color(0xFFB45CFF),Color(0xFF37206D)])),child:const Icon(Icons.mic)),title:Text(r),subtitle:const Text('غرفة صوتية • 8 مايكات'),trailing:const Icon(Icons.arrow_forward_ios,size:16),onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>RoomPage(name:r))))))]),const Center(child:Text('الأصدقاء')),const Center(child:Text('الرسائل')),const Center(child:Text('أنا'))];return Scaffold(appBar:AppBar(title:const Text('فرح شات')),body:SafeArea(child:pages[index]),bottomNavigationBar:NavigationBar(selectedIndex:index,onDestinationSelected:(v)=>setState(()=>index=v),destinations:const[NavigationDestination(icon:Icon(Icons.home_outlined),label:'الرئيسية'),NavigationDestination(icon:Icon(Icons.people_outline),label:'الأصدقاء'),NavigationDestination(icon:Icon(Icons.chat_bubble_outline),label:'الرسائل'),NavigationDestination(icon:Icon(Icons.person_outline),label:'أنا')]));}}
class RoomPage extends StatefulWidget{final String name;const RoomPage({super.key,required this.name});@override State<RoomPage> createState()=>_RoomPageState();}
class _RoomPageState extends State<RoomPage>{final occupied=<int>{};@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text(widget.name)),body:Column(children:[Container(margin:const EdgeInsets.all(12),height:150,decoration:BoxDecoration(borderRadius:BorderRadius.circular(24),gradient:const LinearGradient(colors:[Color(0xFF29114F),Color(0xFF0E1838)])),child:const Center(child:Icon(Icons.graphic_eq_rounded,size:76,color:Color(0xFFD7A7FF)))),Expanded(child:GridView.builder(padding:const EdgeInsets.all(18),itemCount:8,gridDelegate:const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:4,mainAxisSpacing:22,crossAxisSpacing:18),itemBuilder:(c,i){final on=occupied.contains(i);return InkWell(onTap:()=>setState(()=>on?occupied.remove(i):occupied.add(i)),child:Column(children:[Expanded(child:Container(decoration:BoxDecoration(shape:BoxShape.circle,gradient:LinearGradient(colors:on?[const Color(0xFFFFC857),const Color(0xFF9C4DFF)]:[const Color(0xFF35205C),const Color(0xFF15152D)])),child:Icon(on?Icons.person:Icons.mic))),const SizedBox(height:6),Text(on?'مشغول':'مايك '+(i+1).toString(),style:const TextStyle(fontSize:11))]));})),Padding(padding:const EdgeInsets.fromLTRB(12,4,12,14),child:Row(children:[Expanded(child:TextField(decoration:InputDecoration(hintText:'اكتب رسالة...',filled:true,fillColor:const Color(0xFF15152B),border:OutlineInputBorder(borderRadius:BorderRadius.all(Radius.circular(28)),borderSide:BorderSide.none)))),IconButton(onPressed:(){},icon:const Icon(Icons.card_giftcard,color:Color(0xFFFFC857))) ]))]));}}
